import java.io.*;

public class Main {
    private static long parseLong(String s) {
        int sign = 1;
        int index = 0;

        if (s.charAt(0) == '-') {
            sign = -1;
            index++;
        } else if (s.charAt(0) == '+') {
            index++;
        }

        int radix = 10;
        if (index < s.length() && s.charAt(index) == '0') {
            if (index + 1 < s.length()) {
                char c = s.charAt(index + 1);
                if (c == 'x' || c == 'X') {
                    radix = 16;
                    index += 2;
                } else if (c == 'b' || c == 'B') {
                    radix = 2;
                    index += 2;
                } else if (c == 'o' || c == 'O') {
                    radix = 8;
                    index += 2;
                } else {
                    radix = 8;
                    index++;
                }
            }
        }

        if (index >= s.length()) {
            return 0;
        }
        return sign * Long.parseLong(s.substring(index), radix);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer tokenizer = new StreamTokenizer(reader);
        tokenizer.resetSyntax();
        tokenizer.whitespaceChars(0, ' ');
        tokenizer.wordChars('!', 255);

        tokenizer.nextToken();
        long a = parseLong(tokenizer.sval);
        tokenizer.nextToken();
        long c = parseLong(tokenizer.sval);

        long b = 0;
        int i = 1;
        long[] x = new long[105];
        long[] y = new long[105];

        for (; a + c > 0; i++) {
            x[i] = a % 3;
            a /= 3;
            y[i] = c % 3;
            c /= 3;
        }

        while (i > 1) {
            i--;
            b = b * 3 + ((y[i] - x[i] + 3) % 3);
        }

        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
        writer.write(Long.toString(b));
        writer.newLine();
        writer.flush();
    }
}

